from PIL import Image
import numpy as np, glob, re, json

ITEMS = {
 'general':  'the-general-keaton-and-bruckman-1926-high-quality-1080p-t-o-p-swu-fc',
 'kid':      'the-kid_202509',
 'metropolis':'metropolis-1927_202511',
 'potemkin': 'BattleshipPotemkin1925',
 '39steps':  'the-39-steps-1935',
 'allquiet': 'all-quiet-on-the-western-front-1930_202407',
 'joan':     'passion-joan-of-arc',
}
def thumb_lum(f):
    a = np.asarray(Image.open(f).convert('RGB')).astype(float).mean(axis=2)
    rows = a.mean(axis=1); cols = a.mean(axis=0)
    rr = np.where(rows>12)[0]; cc = np.where(cols>12)[0]
    if len(rr)==0 or len(cc)==0:
        return a.mean()  # fully dark frame
    return a[rr[0]:rr[-1]+1, cc[0]:cc[-1]+1].mean()

def profile(pref):
    files = sorted(glob.glob(f'/tmp/thumbs/{pref}_*.jpg'))
    ts, lum = [], []
    for f in files:
        ts.append(int(re.search(r'_(\d+)\.jpg', f).group(1)))
        lum.append(thumb_lum(f))
    return np.array(ts,float), np.array(lum)

mine = np.load('/tmp/profile.npy')
def smooth(y,k):
    ker=np.ones(2*k+1)/(2*k+1)
    return np.convolve(np.pad(y,k,mode='edge'),ker,mode='valid')

def compare(pref,k=3):
    ts,lum = profile(pref)
    T = ts.max(); x = ts/T
    xi=(x*999).round().clip(0,999).astype(int)
    ref = mine[xi]
    a=smooth(lum,k); b=smooth(ref,k)
    A=a-a.mean(); B=b-b.mean()
    c=(A*B).sum()/np.sqrt((A*A).sum()*(B*B).sum())
    return c, lum.mean(), T, len(ts)

prof={}
for name,pref in ITEMS.items():
    ts,lum=profile(pref)
    prof[name]={'t':ts.tolist(),'l':[round(v,1) for v in lum]}
    res={k:compare(pref,k)[0] for k in (1,2,3,5,7,10)}
    c,mean,T,n = compare(pref,5)
    print(f"{name:10s} n={n:3d} {T/60:5.1f}min mean={mean:5.1f} corr(k1..10)=", " ".join(f"{v:+.2f}" for v in res.values()))
json.dump(prof, open('/tmp/thumb_profiles.json','w'))
EOF

